/// <reference types="node" />
// The module 22 contract, as the API generates it from its own Zod schemas (apps/api/src/channels/webContract.json,
// regenerated by webContract.ts and kept current by webContract.test.ts there). apps/web does not depend on
// @realty/api, so the contract is read as data, like shell/errorMessages.test.ts reads errors.ts.
//
// The web's contract tests use it two ways: every request a client sends must satisfy the route's request schema
// (exactly what the API's Zod validation accepts), and every response a fake answers with must satisfy the route's
// response schema (exactly what the API's serializer can emit). An API change regenerates the JSON, and a client
// that no longer fits fails here.
//
// `violations` implements the part of JSON Schema (2020-12) that z.toJSONSchema emits for these routes. A keyword it
// does not know is reported as a violation, so a new kind of schema fails loudly instead of passing unchecked.
// Lengths count UTF-16 code units, as Zod's .min/.max do (the API's real check).
import { readFileSync } from 'node:fs';
import { dirname, resolve } from 'node:path';
import { fileURLToPath } from 'node:url';

export type Schema = { [k: string]: unknown };

export interface RouteContract {
  inputKeys: string[];
  body: Schema | null;
  query: Schema | null;
  response: Schema;
}

export interface Contract {
  routes: Record<string, RouteContract>;
  errors: Record<string, number>;
  webChat: { widgetKey: string; sessionToken: string; nameMax: number; messageMax: number };
}

const here = dirname(fileURLToPath(import.meta.url));
export const CONTRACT_FILE = resolve(here, '../../../api/src/channels/webContract.json');
export const contract: Contract = JSON.parse(readFileSync(CONTRACT_FILE, 'utf8')) as Contract;

/** The contract route of a concrete request ("POST", "/public/chat/wk_…/start" → "POST /public/chat/:widgetToken/start"). */
export function routeFor(method: string, path: string): string | null {
  const p = path.replace(/^\/api(?=\/)/, '').split('?')[0]!;
  for (const key of Object.keys(contract.routes)) {
    const [m, pattern] = key.split(' ') as [string, string];
    if (m !== method.toUpperCase()) continue;
    const re = new RegExp(`^${pattern.replace(/:[A-Za-z]+/g, '[^/]+')}$`);
    if (re.test(p)) return key;
  }
  return null;
}

const KNOWN = new Set(['type', 'enum', 'const', 'anyOf', 'properties', 'required', 'additionalProperties', 'items', 'minItems', 'maxItems', 'minLength', 'maxLength', 'pattern', 'format', 'minimum', 'maximum', '$ref', '$defs', 'default', 'description']);

const typeOf = (v: unknown): string => (v === null ? 'null' : Array.isArray(v) ? 'array' : Number.isInteger(v) ? 'integer' : typeof v);
const isType = (v: unknown, t: string) => t === typeOf(v) || (t === 'number' && typeof v === 'number');

/** Every way `value` breaks `schema` (with `root` for "#/$defs/…" references); [] when it satisfies it. */
export function violations(schema: Schema, value: unknown, path = '', root: Schema = schema): string[] {
  const out: string[] = [];
  const at = path || '/';
  for (const k of Object.keys(schema)) if (!KNOWN.has(k)) out.push(`${at}: the contract uses "${k}", which this checker does not implement`);
  if (typeof schema.$ref === 'string') {
    const m = /^#\/\$defs\/(.+)$/.exec(schema.$ref);
    const target = m ? (root.$defs as Record<string, Schema> | undefined)?.[m[1]!] : undefined;
    if (!target) return [...out, `${at}: unresolvable ${schema.$ref}`];
    return [...out, ...violations(target, value, path, root)];
  }
  if (Array.isArray(schema.anyOf)) {
    const branches = (schema.anyOf as Schema[]).map((s) => violations(s, value, path, root));
    if (!branches.some((b) => b.length === 0)) out.push(`${at}: matches none of anyOf (${branches.map((b) => b[0]).join(' | ')})`);
    return out;
  }
  if (schema.type !== undefined) {
    const types = Array.isArray(schema.type) ? (schema.type as string[]) : [schema.type as string];
    if (!types.some((t) => isType(value, t))) return [...out, `${at}: expected ${types.join(' or ')}, got ${typeOf(value)}`];
  }
  if (schema.const !== undefined && value !== schema.const) out.push(`${at}: expected ${JSON.stringify(schema.const)}`);
  if (Array.isArray(schema.enum) && !(schema.enum as unknown[]).includes(value)) out.push(`${at}: ${JSON.stringify(value)} is not one of ${JSON.stringify(schema.enum)}`);
  if (typeof value === 'string') {
    if (typeof schema.minLength === 'number' && value.length < schema.minLength) out.push(`${at}: shorter than ${schema.minLength}`);
    if (typeof schema.maxLength === 'number' && value.length > schema.maxLength) out.push(`${at}: longer than ${schema.maxLength}`);
    if (typeof schema.pattern === 'string' && !new RegExp(schema.pattern, 'u').test(value)) out.push(`${at}: does not match ${schema.pattern}`);
  }
  if (typeof value === 'number') {
    if (typeof schema.minimum === 'number' && value < schema.minimum) out.push(`${at}: below ${schema.minimum}`);
    if (typeof schema.maximum === 'number' && value > schema.maximum) out.push(`${at}: above ${schema.maximum}`);
  }
  if (Array.isArray(value)) {
    if (typeof schema.minItems === 'number' && value.length < schema.minItems) out.push(`${at}: fewer than ${schema.minItems} items`);
    if (typeof schema.maxItems === 'number' && value.length > schema.maxItems) out.push(`${at}: more than ${schema.maxItems} items`);
    if (schema.items && typeof schema.items === 'object') value.forEach((v, i) => out.push(...violations(schema.items as Schema, v, `${path}/${i}`, root)));
  }
  if (value !== null && typeof value === 'object' && !Array.isArray(value)) {
    const o = value as Record<string, unknown>;
    const props = (schema.properties ?? {}) as Record<string, Schema>;
    for (const r of (schema.required ?? []) as string[]) if (!(r in o) || o[r] === undefined) out.push(`${path}/${r}: required`);
    for (const [k, v] of Object.entries(o)) {
      if (v === undefined) continue;
      if (props[k]) out.push(...violations(props[k], v, `${path}/${k}`, root));
      else if (schema.additionalProperties === false) out.push(`${path}/${k}: not allowed`);
      else if (schema.additionalProperties && typeof schema.additionalProperties === 'object') out.push(...violations(schema.additionalProperties as Schema, v, `${path}/${k}`, root));
    }
  }
  return out;
}

/** What the API would refuse in this request (422 VALIDATION_FAILED); [] when it accepts it. */
export function requestViolations(key: string, body: unknown, query: Record<string, string>): string[] {
  const r = contract.routes[key];
  if (!r) return [`${key}: not a contract route`];
  const out: string[] = [];
  if (r.body) out.push(...violations(r.body, body).map((v) => `body ${v}`));
  else if (body !== undefined) out.push('body: this route takes none');
  if (r.query) out.push(...violations(r.query, query).map((v) => `query ${v}`));
  else if (Object.keys(query).length > 0) out.push('query: this route takes none');
  return out;
}

/** What in this 200 body the API could never send for the route; [] when it could. */
export function responseViolations(key: string, body: unknown): string[] {
  const r = contract.routes[key];
  return r ? violations(r.response, body) : [`${key}: not a contract route`];
}

export interface Exchange {
  /** the contract route ("POST /public/chat/:widgetToken/start") */
  key: string;
  url: URL;
  body: unknown;
  query: Record<string, string>;
  credentials: RequestCredentials | undefined;
}

export interface Answer {
  status: number;
  body?: unknown;
}

/**
 * A fetch that plays the API by its contract, for clients that take a fetch (the widget's chatApi): a URL that is no
 * contract route is 404; a request the API would refuse is 422 VALIDATION_FAILED and is recorded in `problems`; and
 * `answer` may only reply with what the API can send (a 200 body its response schema accepts, or an error whose
 * status is the contract's for its code), else the call throws, so a fake can never drift from the real API.
 */
export function contractFetch(answer: (x: Exchange) => Answer | Promise<Answer>, seen: Exchange[] = [], problems: string[] = []): (input: string, init?: RequestInit) => Promise<Response> {
  return async (input, init = {}) => {
    const url = new URL(input, 'https://app.example.test');
    const method = (init.method ?? 'GET').toUpperCase();
    const key = routeFor(method, url.pathname);
    const reply = (a: Answer) => new Response(a.body === undefined ? '' : JSON.stringify(a.body), { status: a.status, headers: { 'content-type': 'application/json' } });
    if (!key) return reply(apiError('NOT_FOUND'));
    const body = typeof init.body === 'string' ? (JSON.parse(init.body) as unknown) : undefined;
    const query = Object.fromEntries(url.searchParams);
    const x: Exchange = { key, url, body, query, credentials: init.credentials };
    seen.push(x);
    const bad = requestViolations(key, body, query);
    if (bad.length > 0) {
      problems.push(...bad.map((b) => `${key} ${b}`));
      return reply(apiError('VALIDATION_FAILED', { issues: bad.map((b) => ({ path: b.split(' ')[1]!.replace(/:$/, ''), code: 'invalid' })) }));
    }
    const a = await answer(x);
    if (a.status === 200) {
      const wrong = responseViolations(key, a.body);
      if (wrong.length > 0) throw new Error(`the fake answered ${key} with a body the API never sends: ${wrong.join('; ')}`);
    } else {
      const code = (a.body as { error?: { code?: unknown } } | undefined)?.error?.code;
      if (typeof code !== 'string' || contract.errors[code] !== a.status) throw new Error(`the fake answered ${key} with ${a.status} ${String(code)}, which is not how the API answers that code`);
    }
    return reply(a);
  };
}

/** An error exactly as the API sends it: the contract's status for the code, `{error: {code, requestId, details?}}`. */
export function apiError(code: string, details?: Record<string, unknown>): { status: number; body: { error: { code: string; requestId: string; details?: Record<string, unknown> } } } {
  const status = contract.errors[code];
  if (status === undefined) throw new Error(`${code} is not an error code of the contract`);
  return { status, body: { error: { code, requestId: '01900000-0000-7000-8000-0000000000ee', ...(details ? { details } : {}) } } };
}
